  addFeatureCSS();

  function screenHTML(id,title,tab,bodyId,subtitle) {
    return `<div class="screen feature-screen" id="${id}"><div class="sb"><span>9:41</span><span>● ● ● ▰</span></div><div class="scroll"><div class="feature-head"><button class="icobtn" data-go="scr-profile" aria-label="${esc(tx('back'))}">‹</button><div><h2>${esc(title)}</h2><p>${esc(subtitle||'')}</p></div><span class="grow"></span><span class="local-badge">${esc(tx('localDemo'))}</span></div><div id="${bodyId}">${bodyId==='settingsHost'?'': ''}</div></div><div class="tb" data-active="${tab}"></div></div>`;
  }
  function addScreens() {
    const anchor=document.querySelector('#toast');
    const screens=[
      screenHTML('scr-settings',tx('settings'),'profile','settingsHost'),
      screenHTML('scr-premium',tx('premium'),'profile','premiumHost',tx('noPlanPrice')),
      screenHTML('scr-achievements',tx('achievements'),'profile','achievementsHost'),
      screenHTML('scr-friends',tx('findFriends'),'profile','friendsHost')
    ].join('');
    if (anchor) anchor.insertAdjacentHTML('beforebegin',screens); else phone.insertAdjacentHTML('beforeend',screens);
    phone.insertAdjacentHTML('beforeend',`<div class="feature-modal" id="featureModal" role="dialog" aria-modal="true"><div class="feature-modal-card"><div class="feature-modal-head"><h3 id="featureModalTitle"></h3><button class="feature-modal-close" data-close-modal aria-label="Close">×</button></div><div id="featureModalBody"></div></div></div>`);
  }
  addScreens();
  if (I18N.en) I18N.en.premium='Premium';
  if (I18N.tk) I18N.tk.premium='Premium';
  if (I18N.ru) I18N.ru.premium='Premium';
  for (let i=TABS.length-1;i>=0;i--) if(TABS[i][0]==='premium') TABS.splice(i,1);

  function openModal(title, html) {
    const m=document.querySelector('#featureModal');
    if(!m) return;
    m.classList.remove('reward-chest-mode');
    document.querySelector('#featureModalTitle').textContent=title;
    document.querySelector('#featureModalBody').innerHTML=html;
    m.classList.add('on');
  }
  function closeModal() { const m=document.querySelector('#featureModal'); if(m)m.classList.remove('on','reward-chest-mode'); }
  function showToast(message) {
    if (typeof toast==='function') toast(message);
    else if (toastEl) { toastEl.textContent=message; toastEl.classList.add('show'); setTimeout(()=>toastEl.classList.remove('show'),2200); }
  }
  document.addEventListener('click',e=>{
    if(e.target.closest('[data-close-modal]') || e.target.id==='featureModal') closeModal();
  });

  function userName() { return S.user && S.user.name ? S.user.name : 'Aria Johnson'; }
  function userNick() { const saved=S.user&&S.user.nick;if(saved)return saved;const base=userName().toLowerCase().replace(/[^\p{L}\p{N}_.]+/gu,'.').replace(/^\.|\.$/g,'').slice(0,20);return base.length>=3?base:'aria'; }
  function currentCoverBook() { return getBook(FX.lastBook || 'beg'); }
  function renderHeartLabels() {
    const now=Date.now();
    if (!S.premium && FX.hearts<MAX_HEARTS) {
      const recovered=Math.floor((now-FX.heartUpdatedAt)/HEART_REGEN_MS);
      if(recovered>0){FX.hearts=Math.min(MAX_HEARTS,FX.hearts+recovered);FX.heartUpdatedAt+=recovered*HEART_REGEN_MS;if(FX.hearts===MAX_HEARTS)FX.heartUpdatedAt=now;saveFeatureState();}
    } else if (S.premium) FX.hearts=MAX_HEARTS;
    const text=S.premium?'∞':`${FX.hearts}/${MAX_HEARTS}`;
    document.querySelectorAll('[data-heart-count]').forEach(el=>el.textContent=text);
    const homeLives=document.querySelector('#homeLives');if(homeLives){homeLives.setAttribute('aria-label',`${tx('hearts')}: ${text}`);const label=homeLives.querySelector('.life-label');if(label)label.textContent=tx('hearts');}
    document.querySelectorAll('.hp').forEach(hp=>hp.innerHTML=`<svg><use href="#i-heart"/></svg><span data-heart-count>${text}</span>`);
  }
