  function formatStudyTime(seconds) {
    const n=Math.max(0,Math.floor(Number(seconds)||0)),h=Math.floor(n/3600),m=Math.floor((n%3600)/60),s=n%60;
    const hu=tx('hourShort'),mu=tx('minuteShort'),su=tx('secondShort');
    if(h)return `${h}${hu}${m?` ${m}${mu}`:''}`;
    if(m)return `${m}${mu}`;
    return `${s}${su}`;
  }
  function renderWeeklyActivity() {
    const bars=document.querySelector('#scr-home .bars'); if(!bars)return;
    const start=weekStart(new Date()), labels=[], vals=[], dailyTargetSeconds=2*60*60;
    for(let i=0;i<7;i++){
      const d=new Date(start);d.setDate(start.getDate()+i);const k=dateKey(d),a=FX.activity[k]||{};
      labels.push(d);vals.push(Math.max(0,Number(a.studySeconds)||0));
    }
    const cols=[...bars.querySelectorAll('.barw')];
    cols.forEach((col,i)=>{
      const d=labels[i],seconds=vals[i],bar=col.querySelector('.bar'),label=col.querySelector('span');
      if(bar){bar.style.height=(seconds?Math.max(5,Math.round(78*Math.min(seconds,dailyTargetSeconds)/dailyTargetSeconds)):5)+'px';bar.classList.toggle('dim',!seconds);bar.title=`${formatStudyTime(seconds)} focused study`;}
      col.classList.toggle('now',dateKey(d)===dateKey(new Date()));
      if(label)label.textContent=new Intl.DateTimeFormat(S.lang==='tk'?'tk-TM':S.lang==='ru'?'ru-RU':'en-GB',{weekday:'short'}).format(d).slice(0,2);
      col.title=`${dateKey(d)} · ${formatStudyTime(seconds)} focused study`;
    });
    const note=document.querySelector('#weekActivityNote');
    if(note){const total=vals.reduce((a,b)=>a+b,0);note.textContent=`${tx('weekStudySummary',{time:formatStudyTime(total)})} · ${tx('weeklyScaleHint')}`;}
  }
