    const settingsNick=document.querySelector('#settingsProfileNick');if(settingsNick)settingsNick.textContent='@'+userNick();
    const settingsGender=document.querySelector('#settingsProfileGender');if(settingsGender)settingsGender.textContent=`${tx('gender')}: ${genderLabel}`;
    const settingsSchool=document.querySelector('#settingsProfileSchool');if(settingsSchool)settingsSchool.textContent=`${tx('learningCenter')}: ${user.school||tx('schoolNotSet')}`;
    const addProfile=document.querySelector('#settingsAddProfileBtn');if(addProfile)addProfile.textContent=(user.profileCreated||user.email||user.phone)?tx('editProfile'):tx('addProfile');
    const pf=document.querySelector('#pfName');if(pf)pf.textContent=userName()+(S.premium?' 👑':'');
    const avatar=document.querySelector('#pfAv');if(avatar&&(S.avatar||user.avatar))avatar.src=S.avatar||user.avatar;
    const {state,key,following}=currentSocial();
    const followers=Object.entries(state.following).filter(([id,arr])=>id!==key&&(arr||[]).includes(key)).length;
    const followerCount=document.querySelector('#profileFollowersCount');if(followerCount)followerCount.textContent=String(followers);
    const followingCount=document.querySelector('#profileFollowingCount');if(followingCount)followingCount.textContent=String(following.length);
    const catalog=achievementCatalog(),earned=catalog.filter(achievementEarned),n=earned.length;
    const achCount=document.querySelector('#profileAchievementCount');if(achCount)achCount.textContent=tx('achievementCount',{n});
    const achCard=document.querySelector('#scr-profile .achs')?.closest('.card');
    if(achCard){const lab=achCard.querySelector('.lab');if(lab)lab.textContent=`${tx('achievements').toUpperCase()} · ${n}/50`;const mini=achCard.querySelector('.achs');if(mini){const preview=(earned.length?earned:catalog.slice(0,4)).slice(0,4);mini.innerHTML=preview.map(a=>`<div class="card ach${achievementEarned(a)?'':' feature-locked-badge'}"><span>${a.icon}</span><b>${esc(a.title)}</b></div>`).join('');}}
    const bookStats=document.querySelector('#scr-profile [data-profile-analytics]');if(bookStats){const vals=bookStats.querySelectorAll('b');if(vals[1])vals[1].textContent=String(FX.totalWords);if(vals[2])vals[2].textContent=(FX.bestAccuracy||0)+'%';}
