  function editProfile() {
    const current=S.user||{},currentNick=userNick();
    const gender=current.gender||'',hasProfile=!!(current.profileCreated||current.email||current.phone);
    openModal(tx(hasProfile?'editProfile':'addProfile'),`<p class="feature-note">${esc(tx('profileEditHint'))}</p>
      <label class="feature-muted" for="editProfileName">${esc(tx('displayName'))}</label>
      <input id="editProfileName" class="feature-input" maxlength="60" value="${esc(current.name||userName())}" autocomplete="name">
      <label class="feature-muted" for="editProfileNick" style="display:block;margin-top:10px">${esc(tx('nickname'))}</label>
      <input id="editProfileNick" class="feature-input" maxlength="20" value="${esc(currentNick)}" autocomplete="nickname">
      <label class="feature-muted" for="editProfileGender" style="display:block;margin-top:10px">${esc(tx('gender'))}</label>
      <select id="editProfileGender" class="feature-input feature-select"><option value="" ${gender===''?'selected':''}>${esc(tx('genderNotSet'))}</option><option value="female" ${gender==='female'?'selected':''}>${esc(tx('female'))}</option><option value="male" ${gender==='male'?'selected':''}>${esc(tx('male'))}</option><option value="unspecified" ${gender==='unspecified'?'selected':''}>${esc(tx('preferNot'))}</option></select>
      <label class="feature-muted" for="editProfileSchool" style="display:block;margin-top:10px">${esc(tx('learningCenter'))}</label>
      <input id="editProfileSchool" class="feature-input" maxlength="100" value="${esc(current.school||'')}" autocomplete="organization">
      <p class="feature-note profile-edit-error" id="profileEditError" role="alert"></p>
      <button class="feature-btn" id="saveProfileBtn">${esc(tx('saveProfile'))}</button>`);
    const body=document.querySelector('#featureModalBody');
    const saveButton=body&&body.querySelector('#saveProfileBtn');if(!saveButton)return;
    saveButton.onclick=()=>{
      const name=String(body.querySelector('#editProfileName')?.value||'').trim();
      const nick=String(body.querySelector('#editProfileNick')?.value||'').trim();
      const selectedGender=String(body.querySelector('#editProfileGender')?.value||'');
      const school=String(body.querySelector('#editProfileSchool')?.value||'').trim();
      const error=body.querySelector('#profileEditError');
      if(name.length<2){if(error)error.textContent=tx('displayNameRequired');return;}
      if(!/^[\p{L}\p{N}_.]{3,20}$/u.test(nick)){if(error)error.textContent=tx('nicknameInvalid');return;}
      const oldUser=S.user||{},oldKey=getUserKey(oldUser),users=readUsers();
      const taken=Object.entries(users).some(([id,u])=>id!==oldKey&&String((u&&u.nick)||'').toLowerCase()===nick.toLowerCase());
      if(taken){if(error)error.textContent=tx('nicknameTaken');return;}
      const next=Object.assign({},oldUser,{name,nick,gender:selectedGender,school,profileCreated:true});
      const newKey=getUserKey(next),oldEntry=users[oldKey]||{};
      if(oldKey!==newKey&&users[oldKey])delete users[oldKey];
      users[newKey]=Object.assign({},users[newKey]||{},oldEntry,{n:nick,name,nick,gender:selectedGender,school,profileCreated:true,avatar:S.avatar||(oldUser.avatar||oldEntry.avatar||'')});
      try{localStorage.setItem(USERS_KEY,JSON.stringify(users));}catch(_){}
      if(oldKey!==newKey){
        const ss=socialState(),merged=[...new Set([...(ss.following[oldKey]||[]),...(ss.following[newKey]||[])])];
        if(merged.length)ss.following[newKey]=merged;delete ss.following[oldKey];
        Object.keys(ss.following).forEach(id=>{ss.following[id]=[...new Set((ss.following[id]||[]).map(x=>x===oldKey?newKey:x))];});saveSocial(ss);
      }
      S.user=next;if(S.avatar)S.user.avatar=S.avatar;
      if(typeof save==='function')save();
      if(typeof applyProfile==='function')applyProfile();else renderProfileExtras();
      closeModal();showToast(tx('profileSaved'));
    };
  }

  function avatarSvg(emoji,color) {
    const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256"><rect width="256" height="256" rx="48" fill="${color}"/><circle cx="128" cy="116" r="78" fill="rgba(255,255,255,.28)"/><text x="128" y="165" text-anchor="middle" font-size="116" font-family="sans-serif">${emoji}</text></svg>`;
    return 'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(svg)));
  }
  function avatarMaker() {
    const emojis=['🦉','🐻','🐼','🦊','🐸','🐯','🐨','🐰','🐱','🐧','🦄','🐢'];
    const colors=['#9ad27d','#81c7ea','#f6b96b','#dca5e8','#f48d8d','#f4d66d','#82d6bd','#91a7f5'];
    openModal(tx('createAvatar'),`<div class="feature-row" style="justify-content:center"><div id="avatarPreview" class="friend-avatar" style="width:90px;height:90px;border-radius:26px;font-size:50px;background:#9ad27d">🦉</div></div><div class="avatar-options">${emojis.map((e,i)=>`<button class="avatar-choice${i===0?' selected':''}" data-avatar-emoji="${e}">${e}</button>`).join('')}</div><div class="avatar-options">${colors.map((c,i)=>`<button class="color-choice${i===0?' selected':''}" data-avatar-color="${c}" style="background:${c}" aria-label="Color ${i+1}"></button>`).join('')}</div><button class="feature-btn" data-save-avatar>${esc(tx('saveAvatar'))}</button>`);
    let emoji=emojis[0],color=colors[0];
    const body=document.querySelector('#featureModalBody');
    body.onclick=function(e){
      const eb=e.target.closest('[data-avatar-emoji]'),cb=e.target.closest('[data-avatar-color]');
      if(eb){emoji=eb.dataset.avatarEmoji;body.querySelectorAll('[data-avatar-emoji]').forEach(x=>x.classList.toggle('selected',x===eb));}
      if(cb){color=cb.dataset.avatarColor;body.querySelectorAll('[data-avatar-color]').forEach(x=>x.classList.toggle('selected',x===cb));}
      const preview=body.querySelector('#avatarPreview');if(preview){preview.textContent=emoji;preview.style.background=color;}
    };
    body.querySelector('[data-save-avatar]').onclick=()=>{S.avatar=avatarSvg(emoji,color);const U=readUsers(),key=getUserKey();if(U[key]){U[key].avatar=S.avatar;try{localStorage.setItem(USERS_KEY,JSON.stringify(U));}catch(_){}}save();renderProfileExtras();closeModal();showToast(tx('saveAvatar'));};
  }

