    const lang=S.lang||'en',dayUnit=lang==='tk'?'g':lang==='ru'?'д':'d',hourUnit=tx('hourShort'),minuteUnit=tx('minuteShort');
    if(days)return `${days}${dayUnit} ${hours}${hourUnit}`;
