  function renderRussianReviewStep() {
    const r=S.rev,st=r&&r.steps&&r.steps[r.i],lv=document.querySelector('#lv');if(!r||!st||!lv)return;
    const answer=String(st.w.ru||'').trim(),used=new Set([answer.toLowerCase()]),picks=[],pool=WORDS||[];
    let guard=0;
    while(picks.length<3&&pool.length&&guard++<900){
      const item=pool[(Math.random()*pool.length)|0];if(!item||item.en===st.w.en)continue;
      const value=String(item.ru||'').trim(),key=value.toLowerCase();
      if(!value||used.has(key))continue;used.add(key);picks.push(value);
    }
    const options=[answer,...picks].sort(()=>Math.random()-.5);st._opts=options;st._ans=answer;
    const prompt=String(st.w.en||''),sub=String(st.w.ipa||st.w.pos||'');
    const dots=`<div class="dots">${r.steps.map((_,i)=>`<span class="dot ${i<r.i?'done':i===r.i?'cur':''}"></span>`).join('')}</div>`;
    lv.innerHTML=`<div class="vtop"><span class="chip">${esc(tx('chooseRussian'))} · ${r.i+1}/${r.steps.length}</span></div>${dots}<div class="card vcard" style="text-align:center"><div class="vword" style="font-size:26px">${esc(prompt)}</div><div class="vipa" style="margin-top:5px">${esc(sub)}</div></div><div class="opts2" id="mcqOpts">${options.map((value,i)=>`<button class="opt2" data-rm="${i}">${esc(value)}</button>`).join('')}</div><div class="fb" id="rfb"></div>`;
  }
